package com.quizrank.backend.controller;
import com.quizrank.backend.dto.UserResponse; import com.quizrank.backend.entity.User; import com.quizrank.backend.repository.UserRepository; import com.quizrank.backend.service.UserService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController {private final UserService s;private final UserRepository r;public UserController(UserService s,UserRepository r){this.s=s;this.r=r;} @GetMapping("/{id}") public UserResponse get(@PathVariable Integer id){return s.get(id);} @GetMapping("/students") public List<UserResponse> students(){return s.byRole(User.Role.STUDENT);} @GetMapping("/teachers") public List<UserResponse> teachers(){return s.byRole(User.Role.TEACHER);} @GetMapping("/batch/{batch}") public List<UserResponse> batch(@PathVariable String batch){return r.findByRole(User.Role.STUDENT).stream().filter(u->batch.equals(u.getBatch())).map(UserResponse::from).toList();} }
